import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Element-wise addition ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- 2D Average Pooling ----------
avg_pool_cpp_source = "torch::Tensor avg_pool_cuda(torch::Tensor x, int kernel_size, int stride, int padding);"
avg_pool_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm>

__global__ void avgpool_kernel(const float* input, const int k_size, const int stride, const int pad_h, const int pad_w, const int B, const int C, const int H, const int W, const int out_h, const int out_w, float* output) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * C * out_h * out_w) return;

    const int total_out_per_channel = out_h * out_w;
    const int b = idx / (C * total_out_per_channel);
    idx %= (C * total_out_per_channel);
    const int c = idx / total_out_per_channel;
    idx %= total_out_per_channel;
    const int oh = idx / out_w;
    const int ow = idx % out_w;

    float sum = 0.0f;
    int count = 0;
    for (int dy = 0; dy < k_size; ++dy) {
        int in_h_start = oh * stride - pad_h;
        if (in_h_start < 0) in_h_start = 0;
        int in_h_end = in_h_start + k_size + 2 * pad_h;
        if (in_h_end > H) in_h_end = H;
        for (int dw = 0; dw < k_size; ++dw) {
            int in_w_start = ow * stride - pad_w;
            if (in_w_start < 0) in_w_start = 0;
            int in_w_end = in_w_start + k_size + 2 * pad_w;
            if (in_w_end > W) in_w_end = W;
            for (int iy = in_h_start; iy < in_h_end; ++iy) {
                for (int iw = in_w_start; iw < in_w_end; ++iw) {
                    int idx_in = b * C * H * W + c * H * W + iy * W + iw;
                    sum += input[idx_in];
                    ++count;
                }
            }
        }
    }
    output[idx] = sum / static_cast<float>(count);
}

torch::Tensor avg_pool_cuda(torch::Tensor x, int kernel_size, int stride, int padding) {
    auto B = x.size(0);
    auto C = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);
    auto out_h = (H + 2 * padding - kernel_size) / stride + 1;
    auto out_w = (W + 2 * padding - kernel_size) / stride + 1;
    auto out_h = std::max(out_h, 0);
    auto out_w = std::max(out_w, 0);
    auto total_out_elements = B * C * out_h * out_w;
    auto* out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (total_out_elements + block_size - 1) / block_size;

    avgpool_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(),
        kernel_size,
        stride,
        padding,
        padding,
        B,
        C,
        H,
        W,
        out_h,
        out_w,
        out.data_ptr<float>());

    return out;
}
"""

avg_pool = load_inline(
    name="avg_pool_cuda",
    cpp_sources=avg_pool_cpp_source,
    cuda_sources=avg_pool_cuda_source,
    functions=["avg_pool_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

